'use client';

import { useId, useRef, useState } from 'react';
import type { KeyboardEvent } from 'react';
import './expandable-gallery.css';

export interface ExpandableGalleryItem {
  id: string;
  title: string;
  src: string;
  alt: string;
  meta?: string;
  imagePosition?: string;
  href?: string;
  linkLabel?: string;
}

export interface ExpandableGalleryProps {
  items: ExpandableGalleryItem[];
  title?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  className?: string;
}

/** Image panels that expand on selection, with a compact stacked layout. */
export function ExpandableGallery({ items, title = 'Selected projects', defaultValue, onValueChange, className = '' }: ExpandableGalleryProps) {
  const [value, setValue] = useState(defaultValue ?? items[0]?.id ?? '');
  const buttons = useRef(new Map<string, HTMLButtonElement>());
  const instance = useId();
  const headingId = `${instance}-gallery-title`;
  const selected = items.find(item => item.id === value) ?? items[0];
  const selectedIndex = items.findIndex(item => item.id === selected?.id);

  function select(item: ExpandableGalleryItem) {
    if (item.id === selected?.id) return;
    setValue(item.id);
    onValueChange?.(item.id);
  }

  function move(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let nextIndex: number;
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') nextIndex = (index + 1) % items.length;
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') nextIndex = (index - 1 + items.length) % items.length;
    else if (event.key === 'Home') nextIndex = 0;
    else if (event.key === 'End') nextIndex = items.length - 1;
    else return;
    event.preventDefault();
    const next = items[nextIndex];
    select(next);
    const button = buttons.current.get(next.id);
    button?.focus({ preventScroll: true });
    button?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  }

  return (
    <section className={`ac-expandable-gallery ${className}`.trim()} aria-labelledby={title ? headingId : undefined} aria-label={title ? undefined : 'Project gallery'}>
      <header className="ac-expandable-gallery-header">
        {title && <h2 id={headingId}>{title}</h2>}
        <span className="ac-expandable-gallery-count" aria-live="polite" aria-atomic="true">
          <span className="ac-expandable-gallery-sr">Selected image </span>{String(selectedIndex + 1).padStart(2, '0')}<span aria-hidden="true"> / </span><span className="ac-expandable-gallery-sr"> of </span>{String(items.length).padStart(2, '0')}
        </span>
      </header>
      {selected ? <div className="ac-expandable-gallery-panels" role="group" aria-label="Choose an image">
        {items.map((item, index) => {
          const active = item.id === selected.id;
          return <article key={item.id} className="ac-expandable-gallery-panel" data-active={active}>
            <img className="ac-expandable-gallery-image" src={item.src} alt={item.alt} style={{ objectPosition: item.imagePosition }} loading={index === 0 ? 'eager' : 'lazy'} />
            <button
              type="button"
              className="ac-expandable-gallery-select"
              ref={element => { if (element) buttons.current.set(item.id, element); else buttons.current.delete(item.id); }}
              aria-label={`Select ${item.title}`}
              aria-pressed={active}
              onClick={() => select(item)}
              onKeyDown={event => move(event, index)}
            >
              <span className="ac-expandable-gallery-number" aria-hidden="true">{String(index + 1).padStart(2, '0')}</span>
              <span className="ac-expandable-gallery-marker" aria-hidden="true">{active ? '−' : '+'}</span>
              <span className="ac-expandable-gallery-caption"><span className="ac-expandable-gallery-title">{item.title}</span>{item.meta && <span className="ac-expandable-gallery-meta">{item.meta}</span>}</span>
            </button>
            {active && item.href && <a className="ac-expandable-gallery-link" href={item.href} aria-label={item.linkLabel ?? `View ${item.title}`} title={item.linkLabel ?? `View ${item.title}`}><svg width="22" height="22" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14" stroke="currentColor" strokeWidth="1.5" /></svg></a>}
          </article>;
        })}
      </div> : <p className="ac-expandable-gallery-empty">No images to display.</p>}
    </section>
  );
}

.ac-expandable-gallery{--ac-expandable-ink:#262922;--ac-expandable-muted:#73766d;--ac-expandable-line:#d7d9cf;--ac-expandable-radius:5px;--ac-expandable-height:clamp(340px,46cqi,590px);container:ac-expandable-gallery/inline-size;width:100%;min-width:0;color:var(--ac-expandable-ink);font-family:inherit}
.ac-expandable-gallery *{box-sizing:border-box}
.ac-expandable-gallery-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-bottom:18px}
.ac-expandable-gallery-header h2{margin:0;font-size:clamp(19px,2.3cqi,31px);font-weight:500;line-height:1.2;letter-spacing:-.045em}
.ac-expandable-gallery-count{margin-left:auto;flex-shrink:0;font-size:11px;line-height:1.5;font-variant-numeric:tabular-nums;color:var(--ac-expandable-muted);white-space:nowrap}
.ac-expandable-gallery-panels{display:flex;gap:10px;width:100%;height:var(--ac-expandable-height);overflow-x:auto;scrollbar-width:thin;scrollbar-color:var(--ac-expandable-line) transparent}
.ac-expandable-gallery-panel{position:relative;flex:1 0 82px;min-width:0;isolation:isolate;overflow:hidden;border-radius:var(--ac-expandable-radius);background:#41483e;color:#fff;transition:flex-grow .65s cubic-bezier(.22,.75,.2,1)}
.ac-expandable-gallery-panel[data-active=true]{flex-grow:4.5;flex-basis:240px}
.ac-expandable-gallery-image{position:absolute;z-index:-2;inset:0;display:block;width:100%;height:100%;object-fit:cover;transform:scale(1.04);transition:transform .8s cubic-bezier(.22,.75,.2,1)}
.ac-expandable-gallery-panel[data-active=true] .ac-expandable-gallery-image{transform:scale(1)}
.ac-expandable-gallery-select{position:relative;display:grid;grid-template-columns:1fr auto;grid-template-rows:auto 1fr;width:100%;height:100%;padding:22px;border:0;background:linear-gradient(180deg,#07100838 0%,transparent 35%,#07100808 45%,#071008b8 100%);color:inherit;font:inherit;text-align:left;cursor:pointer;appearance:none}
.ac-expandable-gallery-select:focus-visible{outline:2px solid #fff;outline-offset:-7px}
.ac-expandable-gallery-number{font-size:12px;line-height:24px;font-variant-numeric:tabular-nums;text-shadow:0 1px 8px #0005}
.ac-expandable-gallery-marker{display:grid;place-items:center;width:25px;height:25px;border:1px solid #ffffff70;border-radius:50%;font-size:18px;font-weight:400;line-height:1}
.ac-expandable-gallery-caption{grid-column:1/-1;align-self:end;display:flex;align-items:flex-start;gap:11px;flex-direction:column;min-width:0;padding-right:55px}
.ac-expandable-gallery-title{display:block;max-width:17ch;font-size:clamp(30px,4.6cqi,68px);font-weight:400;line-height:1.01;letter-spacing:-.065em;overflow-wrap:anywhere;text-wrap:balance}
.ac-expandable-gallery-meta{font-size:clamp(10px,1cqi,13px);font-weight:400;line-height:1.5;color:#ffffffe6;letter-spacing:.02em}
.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-select{padding:22px 18px}
.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-caption{padding-right:0;overflow:hidden}
.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-title{max-height:calc(var(--ac-expandable-height) - 100px);max-width:none;writing-mode:vertical-rl;transform:rotate(180deg);font-size:clamp(24px,2.5cqi,36px);line-height:1.05;letter-spacing:-.045em;white-space:nowrap;text-wrap:nowrap}
.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-meta{display:none}
.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-marker{display:none}
.ac-expandable-gallery-link{position:absolute;right:22px;bottom:22px;display:grid;place-items:center;width:46px;height:46px;border:1px solid #ffffff85;border-radius:50%;color:#fff;background:#ffffff10;text-decoration:none;transition:background .2s,transform .2s}
.ac-expandable-gallery-link:hover{background:#fff;color:#243025;transform:translate(1px,-1px)}
.ac-expandable-gallery-link:focus-visible{outline:2px solid #fff;outline-offset:4px}
.ac-expandable-gallery-empty{margin:0;padding:40px 0;border-block:1px solid var(--ac-expandable-line);color:var(--ac-expandable-muted);font-size:14px;line-height:1.6}
.ac-expandable-gallery-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@container ac-expandable-gallery (max-width:580px){.ac-expandable-gallery-header{padding-bottom:14px}.ac-expandable-gallery-header h2{font-size:22px}.ac-expandable-gallery-panels{flex-direction:column;height:auto;gap:8px;overflow:visible}.ac-expandable-gallery-panel{flex:0 0 auto;min-height:88px;height:88px;transition:height .55s cubic-bezier(.22,.75,.2,1)}.ac-expandable-gallery-panel[data-active=true]{flex:0 0 auto;height:clamp(300px,90cqi,430px)}.ac-expandable-gallery-select,.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-select{padding:20px}.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-select{grid-template-columns:24px 1fr 26px;grid-template-rows:1fr;align-items:center;column-gap:16px;background:linear-gradient(90deg,#071008a0,#07100825)}.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-caption{grid-column:2;grid-row:1;align-self:center;overflow:visible}.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-title{max-height:none;max-width:none;writing-mode:horizontal-tb;transform:none;font-size:25px;white-space:normal;text-wrap:balance}.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-marker{grid-column:3;grid-row:1;display:grid}.ac-expandable-gallery-title{font-size:clamp(35px,9cqi,52px)}.ac-expandable-gallery-meta{font-size:11px}.ac-expandable-gallery-link{right:20px;bottom:20px;width:43px;height:43px}}
@container ac-expandable-gallery (max-width:300px){.ac-expandable-gallery-header h2{font-size:19px}.ac-expandable-gallery-select,.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-select{padding:16px}.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-select{column-gap:10px}.ac-expandable-gallery-panel[data-active=false] .ac-expandable-gallery-title{font-size:22px}.ac-expandable-gallery-title{font-size:33px}.ac-expandable-gallery-link{right:16px;bottom:16px}}
@media(prefers-reduced-motion:reduce){.ac-expandable-gallery-panel,.ac-expandable-gallery-image,.ac-expandable-gallery-link{transition:none}}

/* Keep photography and white overlay labels; adapt neutral gallery chrome. */
:where([data-theme="dark"], .dark) .ac-expandable-gallery { --ac-expandable-ink: #f0f1e8; --ac-expandable-muted: #b1b6a7; --ac-expandable-line: #505547; }
